import json
import os
import re
import sqlite3
import threading
import time
import uuid
from pathlib import Path

_KEY_RE = re.compile(r'^[A-Za-z0-9_-]{1,80}$')
_KIND_RE = re.compile(r'^[a-z][a-z0-9_]{0,31}$')
_PAYLOAD_RE = re.compile(r'^[0-9a-f]{64}$')

_SCHEMA = """
CREATE TABLE IF NOT EXISTS jobs (
    id TEXT PRIMARY KEY,
    key TEXT NOT NULL,
    kind TEXT NOT NULL,
    payload TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'queued',
    attempts INTEGER NOT NULL DEFAULT 0,
    token TEXT,
    lease_until REAL,
    result TEXT,
    error TEXT,
    created_at REAL NOT NULL,
    UNIQUE(key, kind, payload)
);
CREATE INDEX IF NOT EXISTS idx_jobs_status ON jobs(status);
CREATE INDEX IF NOT EXISTS idx_jobs_lease ON jobs(lease_until);
"""


def _validate_key(key):
    if not isinstance(key, str) or not _KEY_RE.fullmatch(key):
        raise ValueError("invalid key")


def _validate_kind(kind):
    if not isinstance(kind, str) or not _KIND_RE.fullmatch(kind):
        raise ValueError("invalid kind")


def _validate_payload(payload):
    if not isinstance(payload, str) or not _PAYLOAD_RE.fullmatch(payload):
        raise ValueError("invalid payload")


def _validate_now(now):
    if isinstance(now, bool) or not isinstance(now, (int, float)):
        raise ValueError("invalid now")
    if now < 0 or now != now or now == float('inf') or now == float('-inf'):
        raise ValueError("invalid now")


def _validate_ttl(ttl):
    if isinstance(ttl, bool) or not isinstance(ttl, (int, float)):
        raise ValueError("invalid ttl")
    if ttl <= 0 or ttl != ttl or ttl == float('inf') or ttl == float('-inf'):
        raise ValueError("invalid ttl")


def _validate_result(result):
    if result is None:
        return
    try:
        encoded = json.dumps(result, allow_nan=False).encode('utf-8')
    except (TypeError, ValueError):
        raise ValueError("invalid result")
    if len(encoded) > 1048576:
        raise ValueError("result too large")


def _validate_error(error):
    if error is None:
        return
    if not isinstance(error, str) or not error:
        raise ValueError("invalid error")
    if len(error) > 2000:
        raise ValueError("error too long")


class Store:
    def __init__(self, path, max_pending=10000):
        if isinstance(max_pending, bool) or not isinstance(max_pending, int) or max_pending <= 0:
            raise ValueError("invalid max_pending")
        self._path = str(path)
        self._max_pending = max_pending
        self._lock = threading.Lock()
        parent = Path(self._path).parent
        if not parent.exists():
            raise ValueError("parent directory does not exist")
        self._init_db()

    def _init_db(self):
        conn = sqlite3.connect(self._path)
        try:
            conn.execute("PRAGMA journal_mode=WAL")
            conn.execute("PRAGMA busy_timeout=5000")
            conn.executescript(_SCHEMA)
            conn.commit()
        finally:
            conn.close()

    def _connect(self):
        conn = sqlite3.connect(self._path)
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA busy_timeout=5000")
        conn.row_factory = sqlite3.Row
        return conn

    def submit(self, key, kind, payload):
        _validate_key(key)
        _validate_kind(kind)
        _validate_payload(payload)
        with self._lock:
            conn = self._connect()
            try:
                row = conn.execute(
                    "SELECT id, key, kind, payload, status, attempts, token, lease_until, result, error FROM jobs WHERE key=? AND kind=? AND payload=?",
                    (key, kind, payload)
                ).fetchone()
                if row:
                    return self._row_to_dict(row)
                # Check for idempotency conflict: same key with different kind or payload
                conflict = conn.execute(
                    "SELECT id FROM jobs WHERE key=? AND (kind!=? OR payload!=?) LIMIT 1",
                    (key, kind, payload)
                ).fetchone()
                if conflict:
                    raise ValueError("idempotency conflict")
                # Check max_pending
                count = conn.execute(
                    "SELECT COUNT(*) FROM jobs WHERE status IN ('queued', 'running')"
                ).fetchone()[0]
                if count >= self._max_pending:
                    raise OverflowError("max pending exceeded")
                job_id = uuid.uuid4().hex
                now = time.time()
                conn.execute(
                    "INSERT INTO jobs (id, key, kind, payload, status, attempts, token, lease_until, result, error, created_at) VALUES (?, ?, ?, ?, 'queued', 0, NULL, NULL, NULL, NULL, ?)",
                    (job_id, key, kind, payload, now)
                )
                conn.commit()
                row = conn.execute(
                    "SELECT id, key, kind, payload, status, attempts, token, lease_until, result, error FROM jobs WHERE id=?",
                    (job_id,)
                ).fetchone()
                return self._row_to_dict(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def get(self, job_id):
        if not isinstance(job_id, str) or not job_id:
            return None
        conn = self._connect()
        try:
            row = conn.execute(
                "SELECT id, key, kind, payload, status, attempts, token, lease_until, result, error FROM jobs WHERE id=?",
                (job_id,)
            ).fetchone()
            if row is None:
                return None
            return self._row_to_dict(row)
        finally:
            conn.close()

    def claim(self, now, ttl=30.0):
        _validate_now(now)
        _validate_ttl(ttl)
        with self._lock:
            conn = self._connect()
            try:
                # Expire running jobs with attempts >= 3
                conn.execute(
                    "UPDATE jobs SET status='failed', error='max attempts exceeded', token=NULL, lease_until=NULL WHERE status='running' AND attempts>=3 AND lease_until<=?",
                    (now,)
                )
                # Claim oldest eligible job
                row = conn.execute(
                    "SELECT id FROM jobs WHERE (status='queued' OR (status='running' AND lease_until<=?)) ORDER BY created_at ASC LIMIT 1",
                    (now,)
                ).fetchone()
                if row is None:
                    conn.commit()
                    return None
                job_id = row[0]
                new_token = uuid.uuid4().hex
                new_lease = now + ttl
                cur = conn.execute(
                    "UPDATE jobs SET attempts=attempts+1, token=?, lease_until=?, status='running' WHERE id=?",
                    (new_token, new_lease, job_id)
                )
                if cur.rowcount == 0:
                    conn.commit()
                    return None
                conn.commit()
                row = conn.execute(
                    "SELECT id, key, kind, payload, status, attempts, token, lease_until, result, error FROM jobs WHERE id=?",
                    (job_id,)
                ).fetchone()
                return self._row_to_dict(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def finish(self, job_id, token, now, *, result=None, error=None):
        _validate_now(now)
        if (result is None) == (error is None):
            raise ValueError("exactly one of result or error must be provided")
        _validate_result(result)
        _validate_error(error)
        with self._lock:
            conn = self._connect()
            try:
                row = conn.execute(
                    "SELECT id, status, token, lease_until FROM jobs WHERE id=?",
                    (job_id,)
                ).fetchone()
                if row is None:
                    return False
                if row['status'] != 'running':
                    return False
                if row['token'] != token:
                    return False
                if row['lease_until'] is None or row['lease_until'] <= now:
                    return False
                if result is not None:
                    new_status = 'succeeded'
                    result_json = json.dumps(result, allow_nan=False)
                    conn.execute(
                        "UPDATE jobs SET status=?, result=?, error=NULL, token=NULL, lease_until=NULL WHERE id=?",
                        (new_status, result_json, job_id)
                    )
                else:
                    new_status = 'failed'
                    conn.execute(
                        "UPDATE jobs SET status=?, error=?, result=NULL, token=NULL, lease_until=NULL WHERE id=?",
                        (new_status, error, job_id)
                    )
                conn.commit()
                return True
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def _row_to_dict(self, row):
        result = row['result']
        if result is not None:
            try:
                result = json.loads(result)
            except (json.JSONDecodeError, TypeError):
                pass
        return {
            'id': row['id'],
            'key': row['key'],
            'kind': row['kind'],
            'payload': row['payload'],
            'status': row['status'],
            'attempts': row['attempts'],
            'token': row['token'],
            'lease_until': row['lease_until'],
            'result': result,
            'error': row['error'],
        }

